#!/usr/bin/env node
import process from "node:process";
import { mkdir } from "node:fs/promises";
import { dirname, join } from "node:path";
import { DeskMateBridgeCore } from "../src/bridge-core.js";
import { FakeAcpAdapter } from "../src/fake-adapter.js";
import { adapterFor } from "../src/acp-adapter.js";
import { LoopTransportServer } from "../src/transport.js";

const args = process.argv.slice(2);
const index = args.indexOf("--socket");
const backendIndex = args.indexOf("--backend");
const backendName = backendIndex >= 0 ? args[backendIndex + 1] : "fake";
const runtime = process.env.XDG_RUNTIME_DIR;
const socket = index >= 0 ? args[index + 1] : runtime ? join(runtime, "vela-deskmate", "deskmate-link.sock") : null;
if (!socket || !socket.startsWith("/")) throw new Error("provide an absolute --socket path when XDG_RUNTIME_DIR is unavailable");
await mkdir(dirname(socket), { recursive: true, mode: 0o700 });

const adapter = backendName === "fake" ? new FakeAcpAdapter() : adapterFor(backendName, { cwd: process.cwd() });
let transport;
const core = new DeskMateBridgeCore({ adapter, publish: (message) => transport.send(message) });
transport = new LoopTransportServer(socket);
await transport.start({
  onMessage: (message) => core.receive(message).catch((error) => transport.send({ v: 1, type: "error", error: error.message })),
  onLinkState: (state) => { if (state === "down") core.disconnect(); },
  onError: (error) => transport.send({ v: 1, type: "error", error }),
});
await adapter.start();
process.stderr.write(`[deskmate-bridge] ${backendName} backend listening on ${socket}\n`);

const keepAlive = setInterval(() => core.snapshot(), 10_000);
const shutdown = async () => { clearInterval(keepAlive); await core.disconnect(); await adapter.stop(); await transport.stop(); process.exit(0); };
process.on("SIGINT", shutdown); process.on("SIGTERM", shutdown);

// Demo-only hook: deterministic fake permission, never present in a real ACP adapter.
process.stdin.on("data", (chunk) => {
  if (backendName !== "fake" && chunk.toString("utf8").trim()) adapter.submit(chunk.toString("utf8").trim()).catch(() => {});
  if (backendName !== "fake") return;
  if (chunk.toString("utf8").trim() !== "prompt") return;
  adapter.requestPermission({ requestId: "fake-1", sessionId: "fake-session", toolCall: { toolCallId: "fake-tool", title: "Run demo", rawInput: { command: "echo safe", token: "hidden" } }, options: [{ kind: "allow_once", optionId: "allow-1" }, { kind: "reject_once", optionId: "deny-1" }] });
});

#!/usr/bin/env node
import process from "node:process";
import readline from "node:readline";
import { join } from "node:path";
import { nonce, hello, decision } from "../src/protocol.js";
import { LoopTransportClient } from "../src/transport.js";

const args = process.argv.slice(2);
const index = args.indexOf("--socket");
const socket = index >= 0 ? args[index + 1] : process.env.XDG_RUNTIME_DIR ? join(process.env.XDG_RUNTIME_DIR, "vela-deskmate", "deskmate-link.sock") : null;
if (!socket || !socket.startsWith("/")) throw new Error("provide an absolute --socket path when XDG_RUNTIME_DIR is unavailable");
const state = { nonce: nonce(), epoch: null, seq: 0, prompt: null, status: "Offline", msg: "" };
let lastSnapshotAt = 0;
const show = () => {
  console.log(`${state.status}: ${state.msg || "no current activity"}`);
  if (state.prompt) console.log(`  ATTENTION ${state.prompt.tool}: ${state.prompt.hint || "(no summary)"} [once=${state.prompt.canOnce}, deny=${state.prompt.canDeny}]`);
};
const client = new LoopTransportClient(socket);
await client.start({
  onMessage(message) {
    if (message.type === "hello_ack" && message.connection_nonce === state.nonce) { state.epoch = message.epoch; state.seq = 0; return; }
    if (message.connection_nonce !== state.nonce || message.epoch !== state.epoch) return;
    if (message.type === "snapshot") {
      if (message.seq <= state.seq) return;
      if (state.seq && message.seq !== state.seq + 1) { state.status = "Offline"; state.prompt = null; state.epoch = null; client.send(hello(state.nonce)); return; }
      state.seq = message.seq; state.prompt = message.prompt; state.msg = message.msg;
      lastSnapshotAt = Date.now();
      state.status = message.prompt ? "Attention" : message.running > 0 ? "Busy" : "Idle"; show();
    } else if (message.type === "permission_result") console.log(`Permission decision ${message.accepted ? "accepted by ACP" : `failed: ${message.error}`}`);
    else if (message.type === "tool_result") { state.status = "Result"; state.msg = `${message.toolCallId}: ${message.status}`; show(); }
    else if (message.type === "error") console.log(`Link error: ${message.error}`);
  },
  onLinkState(status) { if (status === "down") { state.status = "Offline"; state.prompt = null; console.log("Disconnected"); } },
});
client.send(hello(state.nonce));
const liveness = setInterval(() => {
  if (state.epoch && lastSnapshotAt && Date.now() - lastSnapshotAt > 30_000) {
    state.status = "Offline"; state.prompt = null; state.msg = "snapshot timeout"; lastSnapshotAt = 0; show();
  }
}, 1_000);
const terminal = readline.createInterface({ input: process.stdin, output: process.stdout, prompt: "deskmate> " });
console.log("Commands: status, once, deny, disconnect, quit"); terminal.prompt();
terminal.on("line", (line) => {
  const command = line.trim();
  if (command === "status") show();
  else if (command === "once" || command === "deny") {
    if (!state.prompt || !state.epoch) console.log("No current permission request.");
    else if (command === "once" && !state.prompt.canOnce) console.log("Approve once is unavailable.");
    else if (command === "deny" && !state.prompt.canDeny) console.log("Deny is unavailable.");
    else client.send(decision(state.nonce, state.epoch, state.prompt.id, command));
  } else if (command === "disconnect") client.stop();
  else if (command === "quit" || command === "exit") { clearInterval(liveness); client.stop(); terminal.close(); }
  else if (command) console.log("Commands: status, once, deny, disconnect, quit");
  terminal.prompt();
});

import { spawn } from "node:child_process";
import readline from "node:readline";
import { summarizeArguments } from "./bridge.js";

const READY_DELAY_MS = 1_000;

function delay(milliseconds) { return new Promise((resolve) => setTimeout(resolve, milliseconds)); }

export class StdioAcpAdapter {
  constructor({ backend, command, args = ["acp"], cwd = process.cwd(), env = process.env }) {
    this.backend = backend;
    this.command = command;
    this.args = args;
    this.cwd = cwd;
    this.env = env;
    this.listener = () => {};
    this.pending = new Map();
    this.tools = new Map();
    this.nextId = 1;
    this.child = null;
  }

  onEvent(listener) { this.listener = listener; }

  async start() {
    this.child = spawn(this.command, this.args, { cwd: this.cwd, env: this.env, stdio: ["pipe", "pipe", "pipe"], detached: true });
    this.child.stderr.on("data", () => {}); // stderr is deliberately never forwarded to DeskMate Link.
    this.child.on("error", (error) => {
      for (const entry of this.pending.values()) entry.reject(error);
      this.pending.clear(); this.listener({ type: "text", text: "ACP backend unavailable" });
    });
    this.child.on("exit", () => {
      for (const entry of this.pending.values()) entry.reject(new Error("acp_process_exited"));
      this.pending.clear(); this.listener({ type: "text", text: "ACP backend disconnected" });
    });
    readline.createInterface({ input: this.child.stdout, crlfDelay: Infinity }).on("line", (line) => this.#receive(line));
    const initialized = await this.request("initialize", { protocolVersion: 1, clientCapabilities: {}, clientInfo: { name: "vela-deskmate", version: "0.1.0" } });
    await delay(READY_DELAY_MS);
    const created = await this.request("session/new", { cwd: this.cwd, mcpServers: [] });
    this.sessionId = created.sessionId;
    this.listener({ type: "text", text: `${this.backend} session ready` });
    return initialized;
  }

  async submit(text) {
    return this.request("session/prompt", { sessionId: this.sessionId, prompt: [{ type: "text", text }] });
  }

  async respondPermission(id, result) { this.send({ jsonrpc: "2.0", id, result }); }

  async stop() {
    if (!this.child?.pid) return;
    try { process.kill(-this.child.pid, "SIGTERM"); } catch { this.child.kill("SIGTERM"); }
  }

  request(method, params) {
    const id = this.nextId++;
    this.send({ jsonrpc: "2.0", id, method, params });
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => { this.pending.delete(id); reject(new Error(`${method}_timeout`)); }, 30_000);
      this.pending.set(id, { resolve, reject, timer });
    });
  }

  send(message) { this.child.stdin.write(`${JSON.stringify(message)}\n`); }

  #receive(line) {
    let message;
    try { message = JSON.parse(line); } catch { return; }
    if (message.id !== undefined && (message.result !== undefined || message.error !== undefined)) {
      const entry = this.pending.get(message.id); if (!entry) return;
      clearTimeout(entry.timer); this.pending.delete(message.id);
      if (message.error) entry.reject(new Error(message.error.message ?? "acp_error")); else entry.resolve(message.result);
      return;
    }
    if (message.id !== undefined && message.method === "session/request_permission") {
      const toolCall = message.params?.toolCall ?? {};
      const cached = this.tools.get(toolCall.toolCallId);
      this.listener({ type: "permission_request", params: { ...message.params, requestId: message.id, toolCall: { ...cached, ...toolCall, rawInput: toolCall.rawInput ?? cached?.rawInput } } });
      return;
    }
    if (message.id !== undefined && message.method) {
      this.send({ jsonrpc: "2.0", id: message.id, error: { code: -32601, message: "DeskMate bridge does not implement this ACP client request" } });
      return;
    }
    if (message.method === "session/update" || message.method === "_kiro.dev/session/update") this.#normalize(message.params?.update);
  }

  #normalize(update = {}) {
    const type = update.sessionUpdate;
    if (type === "agent_message_chunk") {
      const text = update.content?.text;
      if (typeof text === "string" && text) this.listener({ type: "text", text });
      return;
    }
    if (type === "tool_call" || type === "tool_call_update") {
      const previous = this.tools.get(update.toolCallId) ?? {};
      this.tools.set(update.toolCallId, { ...previous, ...update, rawInput: update.rawInput ?? previous.rawInput });
      const status = update.status;
      this.listener({ type: "tool", toolCallId: update.toolCallId, title: update.title ?? previous.title ?? "Tool", status: status === "completed" || status === "failed" ? status : "in_progress", summary: summarizeArguments(update.rawInput ?? previous.rawInput) });

